package cl.duoc.tienda.categoria.service;
import cl.duoc.tienda.categoria.dto.*; import cl.duoc.tienda.categoria.model.*; import cl.duoc.tienda.categoria.repository.*; import java.util.*; import org.slf4j.*; import org.springframework.stereotype.Service;
@Service public class CategoriaService { private static final Logger log=LoggerFactory.getLogger(CategoriaService.class); private final CategoriaRepository repo; public CategoriaService(CategoriaRepository r){repo=r;} public List<Categoria> listar(){return repo.findAll();} public Categoria buscar(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Categoria no encontrado: "+id));} public Categoria guardar(CategoriaRequest d){ Categoria e=new Categoria(d.nombre(), d.descripcion()); log.info("Guardando categoria"); return repo.save(e);} public Categoria actualizar(Long id,CategoriaRequest d){buscar(id); Categoria e=new Categoria(d.nombre(), d.descripcion()); e.setId(id); return repo.save(e);} public void eliminar(Long id){buscar(id);repo.deleteById(id);log.info("Categoria eliminado: {}",id);} }
